1	package codex
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/agent"
12		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
13		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15	)
16	
17	// HooksFileName is the hooks config file used by Codex.
18	const HooksFileName = "hooks.json"
19	
20	// entireHookPrefixes identifies Entire hook commands. The "go run" prefix is
21	// retained so hooks installed by older versions are still recognized.
22	var entireHookPrefixes = []string{
23		"entire ",
24		agent.LocalDevHookScript + " ",
25		`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
26	}
27	
28	// InstallHooks installs Codex hooks in .codex/hooks.json.
29	func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
30		repoRoot, err := paths.WorktreeRoot(ctx)
31		if err != nil {
32			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
33			if err != nil {
34				return 0, fmt.Errorf("failed to get current directory: %w", err)
35			}
36		}
37	
38		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
39	
40		// Read existing hooks.json if present
41		var rawHooks map[string]json.RawMessage
42		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
43		if readErr == nil {
44			var hooksFile map[string]json.RawMessage
45			if err := json.Unmarshal(existingData, &hooksFile); err != nil {
46				return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
47			}
48			if hooksRaw, ok := hooksFile["hooks"]; ok {
49				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
50					return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
51				}
52			}
53		}
54	
55		if rawHooks == nil {
56			rawHooks = make(map[string]json.RawMessage)
57		}
58	
59		// Parse event types we manage
60		var sessionStart, userPromptSubmit, stop, postToolUse []MatcherGroup
61		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
62			return 0, err
63		}
64		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
65			return 0, err
66		}
67		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
68			return 0, err
69		}
70		if err := parseHookType(rawHooks, "PostToolUse", &postToolUse); err != nil {
71			return 0, err
72		}
73	
74		if force {
75			sessionStart = removeEntireHooks(sessionStart)
76			userPromptSubmit = removeEntireHooks(userPromptSubmit)
77			stop = removeEntireHooks(stop)
78			postToolUse = removeEntireHooks(postToolUse)
79		}
80	
81		// Build hook commands
82		var cmdPrefix string
83		if localDev {
84			cmdPrefix = agent.LocalDevHookScript + " hooks codex "
85		} else {
86			cmdPrefix = "entire hooks codex "
87		}
88		sessionStartCmd := cmdPrefix + "session-start"
89		useWindowsProductionHooks := agent.UseWindowsProductionHooks(ctx, localDev)
90		if !localDev {
91			sessionStartCmd = agent.WrapProductionJSONWarningHookCommandForOS(sessionStartCmd, agent.WarningFormatSingleLine, useWindowsProductionHooks)
92		}
93		userPromptSubmitCmd := cmdPrefix + "user-prompt-submit"
94		stopCmd := cmdPrefix + "stop"
95		postToolUseCmd := cmdPrefix + "post-tool-use"
96		if !localDev {
97			userPromptSubmitCmd = agent.WrapProductionSilentHookCommandForOS(userPromptSubmitCmd, useWindowsProductionHooks)
98			stopCmd = agent.WrapProductionSilentHookCommandForOS(stopCmd, useWindowsProductionHooks)
99			postToolUseCmd = agent.WrapProductionSilentHookCommandForOS(postToolUseCmd, useWindowsProductionHooks)
100		}
101	
102		count := 0
103	
104		if updated, changed := syncHookCommand(sessionStart, sessionStartCmd); changed {
105			sessionStart = updated
106			count++
107		}
108		if updated, changed := syncHookCommand(userPromptSubmit, userPromptSubmitCmd); changed {
109			userPromptSubmit = updated
110			count++
111		}
112		if updated, changed := syncHookCommand(stop, stopCmd); changed {
113			stop = updated
114			count++
115		}
116		if updated, changed := syncHookCommand(postToolUse, postToolUseCmd); changed {
117			postToolUse = updated
118			count++
119		}
120	
121		if count == 0 {
122			// Still ensure the feature flag is configured even if hooks
123			// were already present (e.g., manually installed).
124			if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
125				return 0, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
126			}
127			return 0, nil
128		}
129	
130		// Marshal modified types back
131		marshalHookType(rawHooks, "SessionStart", sessionStart)
132		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
133		marshalHookType(rawHooks, "Stop", stop)
134		marshalHookType(rawHooks, "PostToolUse", postToolUse)
135	
136		// Preserve existing top-level keys (e.g., $schema) by reusing the parsed file
137		topLevel := make(map[string]json.RawMessage)
138		if readErr == nil {
139			// Re-parse the original file to preserve all top-level keys
140			_ = json.Unmarshal(existingData, &topLevel) //nolint:errcheck // best-effort preservation
141		}
142		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
143		if err != nil {
144			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
145		}
146		topLevel["hooks"] = hooksJSON
147	
148		// Write to file
149		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
150			return 0, fmt.Errorf("failed to create .codex directory: %w", err)
151		}
152	
153		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
154		if err != nil {
155			return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
156		}
157	
158		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
159			return 0, fmt.Errorf("failed to write hooks.json: %w", err)
160		}
161	
162		// Enable the codex_hooks feature in the project-level .codex/config.toml.
163		// This keeps the feature flag per-repo rather than global.
164		if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
165			return count, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
166		}
167	
168		return count, nil
169	}
170	
171	// UninstallHooks removes Entire hooks from Codex hooks.json.
172	func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
173		repoRoot, err := paths.WorktreeRoot(ctx)
174		if err != nil {
175			repoRoot = "."
176		}
177	
178		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
179		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
180		if err != nil {
181			return nil //nolint:nilerr // No hooks.json means nothing to uninstall
182		}
183	
184		var topLevel map[string]json.RawMessage
185		if err := json.Unmarshal(data, &topLevel); err != nil {
186			return fmt.Errorf("failed to parse hooks.json: %w", err)
187		}
188	
189		var rawHooks map[string]json.RawMessage
190		if hooksRaw, ok := topLevel["hooks"]; ok {
191			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
192				return fmt.Errorf("failed to parse hooks: %w", err)
193			}
194		}
195		if rawHooks == nil {
196			return nil
197		}
198	
199		var sessionStart, userPromptSubmit, stop, postToolUse []MatcherGroup
200		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
201			return err
202		}
203		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
204			return err
205		}
206		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
207			return err
208		}
209		if err := parseHookType(rawHooks, "PostToolUse", &postToolUse); err != nil {
210			return err
211		}
212	
213		sessionStart = removeEntireHooks(sessionStart)
214		userPromptSubmit = removeEntireHooks(userPromptSubmit)
215		stop = removeEntireHooks(stop)
216		postToolUse = removeEntireHooks(postToolUse)
217	
218		marshalHookType(rawHooks, "SessionStart", sessionStart)
219		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
220		marshalHookType(rawHooks, "Stop", stop)
221		marshalHookType(rawHooks, "PostToolUse", postToolUse)
222	
223		if len(rawHooks) > 0 {
224			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
225			if err != nil {
226				return fmt.Errorf("failed to marshal hooks: %w", err)
227			}
228			topLevel["hooks"] = hooksJSON
229		} else {
230			delete(topLevel, "hooks")
231		}
232	
233		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
234		if err != nil {
235			return fmt.Errorf("failed to marshal hooks.json: %w", err)
236		}
237		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
238			return fmt.Errorf("failed to write hooks.json: %w", err)
239		}
240		return nil
241	}
242	
243	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
244	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
245		repoRoot, err := paths.WorktreeRoot(ctx)
246		if err != nil {
247			repoRoot = "."
248		}
249	
250		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
251		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
252		if err != nil {
253			return false
254		}
255	
256		var hooksFile HooksFile
257		if err := json.Unmarshal(data, &hooksFile); err != nil {
258			return false
259		}
260	
261		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
262			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
263			hasEntireHook(hooksFile.Hooks.Stop) &&
264			hasEntireHook(hooksFile.Hooks.PostToolUse)
265	}
266	
267	// --- Helpers ---
268	
269	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
270		if data, ok := rawHooks[hookType]; ok {
271			if err := json.Unmarshal(data, target); err != nil {
272				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
273			}
274		}
275		return nil
276	}
277	
278	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
279		if len(groups) == 0 {
280			delete(rawHooks, hookType)
281			return
282		}
283		data, err := jsonutil.MarshalWithNoHTMLEscape(groups)
284		if err != nil {
285			return
286		}
287		rawHooks[hookType] = data
288	}
289	
290	func hookCommandExists(groups []MatcherGroup, command string) bool {
291		for _, group := range groups {
292			for _, hook := range group.Hooks {
293				if hook.Command == command {
294					return true
295				}
296			}
297		}
298		return false
299	}
300	
301	func syncHookCommand(groups []MatcherGroup, command string) ([]MatcherGroup, bool) {
302		if hookCommandExists(groups, command) {
303			return groups, false
304		}
305		if hasEntireHook(groups) {
306			groups = removeEntireHooks(groups)
307		}
308		return addHook(groups, command), true
309	}
310	
311	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
312		entry := HookEntry{
313			Type:    "command",
314			Command: command,
315			Timeout: 30,
316		}
317	
318		// Add to an existing group with null matcher, or create a new one
319		for i, group := range groups {
320			if group.Matcher == nil {
321				groups[i].Hooks = append(groups[i].Hooks, entry)
322				return groups
323			}
324		}
325		return append(groups, MatcherGroup{
326			Matcher: nil,
327			Hooks:   []HookEntry{entry},
328		})
329	}
330	
331	func isEntireHook(command string) bool {
332		return agent.IsManagedHookCommand(command, entireHookPrefixes)
333	}
334	
335	func hasEntireHook(groups []MatcherGroup) bool {
336		for _, group := range groups {
337			for _, hook := range group.Hooks {
338				if isEntireHook(hook.Command) {
339					return true
340				}
341			}
342		}
343		return false
344	}
345	
346	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
347		result := make([]MatcherGroup, 0, len(groups))
348		for _, group := range groups {
349			filtered := make([]HookEntry, 0, len(group.Hooks))
350			for _, hook := range group.Hooks {
351				if !isEntireHook(hook.Command) {
352					filtered = append(filtered, hook)
353				}
354			}
355			if len(filtered) > 0 {
356				group.Hooks = filtered
357				result = append(result, group)
358			}
359		}
360		return result
361	}
362	
363	// configFileName is the Codex config file name.
364	const configFileName = "config.toml"
365	
366	// featureLine is the TOML line that enables the hooks feature. The flag was
367	// renamed from `codex_hooks` to `hooks` in Codex 0.129.0; the old name is
368	// still accepted as a legacy alias but emits a deprecation warning at
369	// every startup. ensureProjectFeatureEnabled rewrites the legacy form when
370	// it sees it.
371	const (
372		featureLine       = "hooks = true"
373		legacyFeatureLine = "codex_hooks = true"
374	)
375	
376	// ensureProjectFeatureEnabled enables the hooks feature for repoRoot.
377	//
378	// Normally that means writing features.hooks = true to the project-level
379	// .codex/config.toml, keeping the flag scoped per-repo. But when repoRoot
380	// lives inside <CODEX_HOME>/agents (a reserved tree Codex recursively scans
381	// for custom agent-role TOML files), a project-local .codex/config.toml
382	// there gets misinterpreted as a malformed agent role definition and
383	// triggers a Codex startup warning (entireio/cli#842). In that case the
384	// flag is scoped to this project via a [projects."<repoRoot>".features]
385	// table in the global config.toml instead, and any stale project-local
386	// config.toml left behind by older entire versions is cleaned up.
387	func ensureProjectFeatureEnabled(repoRoot string) error {
388		codexHome, err := resolveCodexHome()
389		if err == nil && isUnderCodexAgentsDir(repoRoot, codexHome) {
390			return ensureScopedProjectFeatureEnabled(codexHome, repoRoot)
391		}
392		return ensureLocalProjectFeatureEnabled(repoRoot)
393	}
394	
395	// isUnderCodexAgentsDir reports whether repoRoot lives inside
396	// <codexHome>/agents, the reserved tree Codex recursively scans for custom
397	// agent-role TOML files (see developers.openai.com/codex/subagents).
398	func isUnderCodexAgentsDir(repoRoot, codexHome string) bool {
399		agentsDir := filepath.Join(codexHome, "agents")
400		rel, err := filepath.Rel(agentsDir, repoRoot)
401		if err != nil {
402			return false
403		}
404		if rel == "." {
405			return true
406		}
407		// rel escapes agentsDir only when it is exactly ".." or begins with
408		// "../". A plain strings.HasPrefix(rel, "..") check would wrongly reject
409		// a directory literally named "..foo" that really does live under
410		// agentsDir.
411		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
412			return false
413		}
414		return true
415	}
416	
417	// ensureLocalProjectFeatureEnabled writes features.hooks = true to the
418	// project-level .codex/config.toml. This keeps the feature flag per-repo.
419	// Replaces the deprecated codex_hooks = true line if it's present.
420	func ensureLocalProjectFeatureEnabled(repoRoot string) error {
421		configPath := filepath.Join(repoRoot, ".codex", configFileName)
422	
423		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
424		if err != nil && !os.IsNotExist(err) {
425			return fmt.Errorf("failed to read config.toml: %w", err)
426		}
427	
428		content := string(data)
429		hasNew := containsFeatureLine(content, featureLine)
430		hasLegacy := containsFeatureLine(content, legacyFeatureLine)
431		switch {
432		case hasNew && hasLegacy:
433			content = stripLegacyFeatureLine(content)
434		case hasNew:
435			return nil
436		case hasLegacy:
437			content = strings.Replace(content, legacyFeatureLine, featureLine, 1)
438		case strings.Contains(content, "[features]"):
439			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
440		default:
441			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
442				content += "\n"
443			}
444			content += "\n[features]\n" + featureLine + "\n"
445		}
446	
447		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
448			return fmt.Errorf("failed to create .codex directory: %w", err)
449		}
450		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
451			return fmt.Errorf("failed to write config.toml: %w", err)
452		}
453		return nil
454	}
455	
456	// containsFeatureLine checks for an exact line match. A plain
457	// strings.Contains is wrong because "hooks = true" is a substring of
458	// "codex_hooks = true" — without the line-boundary anchor we'd treat the
459	// legacy form as if the new form was already present.
460	func containsFeatureLine(content, line string) bool {
461		for _, raw := range strings.Split(content, "\n") {
462			if strings.TrimSpace(raw) == line {
463				return true
464			}
465		}
466		return false
467	}
468	
469	// stripLegacyFeatureLine removes the deprecated `codex_hooks = true` line
470	// from a TOML config string, dropping a trailing blank line so the file
471	// stays tidy. The new `hooks = true` is added separately by the caller.
472	func stripLegacyFeatureLine(content string) string {
473		idx := strings.Index(content, legacyFeatureLine)
474		if idx < 0 {
475			return content
476		}
477		end := idx + len(legacyFeatureLine)
478		if end < len(content) && content[end] == '\n' {
479			end++
480		}
481		return content[:idx] + content[end:]
482	}
483	
484	// ensureScopedProjectFeatureEnabled writes features.hooks = true scoped to
485	// repoRoot via a [projects."<repoRoot>".features] table in the global
486	// <codexHome>/config.toml, instead of a project-local .codex/config.toml.
487	// This is used when repoRoot falls inside Codex's reserved agents tree; see
488	// ensureProjectFeatureEnabled. It never touches other projects' sections or
489	// unrelated keys in the global config, and cleans up any stale
490	// project-local config.toml an older entire version left behind.
491	func ensureScopedProjectFeatureEnabled(codexHome, repoRoot string) error {
492		if err := writeScopedFeatureToGlobalConfig(codexHome, repoRoot); err != nil {
493			return err
494		}
495		return cleanupStaleReservedTreeConfig(repoRoot)
496	}
497	
498	// writeScopedFeatureToGlobalConfig merges the scoped
499	// [projects."<repoRoot>".features] hooks flag into the global config.toml.
500	// The global file is shared by every repo that enables hooks from inside the
501	// reserved agents tree and is read by Codex at startup, so the
502	// read-modify-write is serialized under a cross-process advisory lock and
503	// swapped in atomically. Two concurrent `entire enable` runs therefore can
504	// neither lose each other's edits (a plain read-modify-write would let the
505	// second writer clobber the first) nor expose a truncated half-written file
506	// to a concurrent reader.
507	func writeScopedFeatureToGlobalConfig(codexHome, repoRoot string) error {
508		if err := os.MkdirAll(codexHome, 0o750); err != nil {
509			return fmt.Errorf("failed to create Codex home directory: %w", err)
510		}
511	
512		configPath := filepath.Join(codexHome, configFileName)
513		release, err := flock.Acquire(configPath + ".lock")
514		if err != nil {
515			return fmt.Errorf("failed to lock global config.toml: %w", err)
516		}
517		defer release()
518	
519		data, err := os.ReadFile(configPath) //nolint:gosec // path resolved from CODEX_HOME or HOME
520		if err != nil && !os.IsNotExist(err) {
521			return fmt.Errorf("failed to read global config.toml: %w", err)
522		}
523	
524		updated, changed := ensureLineInSection(string(data), scopedFeaturesHeader(repoRoot), featureLine)
525		if !changed {
526			return nil
527		}
528		if err := jsonutil.WriteFileAtomic(configPath, []byte(updated), 0o600); err != nil {
529			return fmt.Errorf("failed to write global config.toml: %w", err)
530		}
531		return nil
532	}
533	
534	// scopedFeaturesHeader returns the TOML table header used to scope the
535	// hooks feature to a single project inside the global config.toml, e.g.
536	//
537	//	[projects."/Users/x/.codex/agents/repos/project".features]
538	func scopedFeaturesHeader(repoRoot string) string {
539		return "[projects." + tomlQuoteString(repoRoot) + ".features]"
540	}
541	
542	// tomlQuoteString renders s as a TOML basic (double-quoted) string, escaping
543	// every character TOML requires so the result is always a single, valid,
544	// self-contained key. This is security-critical: repoRoot is an
545	// attacker-influenceable filesystem path that gets embedded into the shared
546	// global config.toml. A path containing a quote, backslash, newline, or other
547	// control character must not be able to terminate the quoted key early and
548	// inject arbitrary TOML — nor split the header across physical lines, which
549	// would also defeat the line-based idempotency check in ensureLineInSection.
550	// Unicode scalar values >= U+0020 (other than " and \) are valid literally in
551	// a TOML basic string and are emitted as-is.
552	func tomlQuoteString(s string) string {
553		var b strings.Builder
554		b.WriteByte('"')
555		for _, r := range s {
556			switch r {
557			case '"':
558				b.WriteString(`\"`)
559			case '\\':
560				b.WriteString(`\\`)
561			case '\b':
562				b.WriteString(`\b`)
563			case '\t':
564				b.WriteString(`\t`)
565			case '\n':
566				b.WriteString(`\n`)
567			case '\f':
568				b.WriteString(`\f`)
569			case '\r':
570				b.WriteString(`\r`)
571			default:
572				if r < 0x20 || r == 0x7f {
573					fmt.Fprintf(&b, `\u%04X`, r)
574				} else {
575					b.WriteRune(r)
576				}
577			}
578		}
579		b.WriteByte('"')
580		return b.String()
581	}
582	
583	// ensureLineInSection inserts line as the first line under the exact TOML
584	// table header in content, creating the table (appended at the end of the
585	// file) if it doesn't already exist. It reports the updated content and
586	// whether a change was made. Like containsFeatureLine, this is a line-based
587	// edit rather than a full TOML parse: it matches a header line by exact
588	// content after trimming surrounding whitespace (so an indented header line
589	// also matches), and a table's body ends at the next line starting with "[".
590	// That's sufficient for the narrow shape this package writes and avoids
591	// touching content it doesn't understand.
592	func ensureLineInSection(content, header, line string) (string, bool) {
593		lines := strings.Split(content, "\n")
594	
595		headerIdx := -1
596		for i, raw := range lines {
597			if strings.TrimSpace(raw) == header {
598				headerIdx = i
599				break
600			}
601		}
602	
603		if headerIdx == -1 {
604			trimmed := strings.TrimRight(content, "\n")
605			if trimmed == "" {
606				return header + "\n" + line + "\n", true
607			}
608			return trimmed + "\n\n" + header + "\n" + line + "\n", true
609		}
610	
611		end := len(lines)
612		for i := headerIdx + 1; i < len(lines); i++ {
613			if strings.TrimSpace(lines[i]) == line {
614				return content, false
615			}
616			if strings.HasPrefix(strings.TrimSpace(lines[i]), "[") {
617				end = i
618				break
619			}
620		}
621	
622		updated := make([]string, 0, len(lines)+1)
623		updated = append(updated, lines[:headerIdx+1]...)
624		updated = append(updated, line)
625		updated = append(updated, lines[headerIdx+1:end]...)
626		updated = append(updated, lines[end:]...)
627		return strings.Join(updated, "\n"), true
628	}
629	
630	// cleanupStaleReservedTreeConfig removes a project-local .codex/config.toml
631	// left behind by an older entire version when repoRoot lives inside
632	// Codex's reserved agents tree. Codex recursively scans that tree for
633	// agent-role TOML files, so a leftover config.toml there keeps triggering
634	// a "malformed agent role definition" warning (entireio/cli#842) even
635	// after upgrading entire. Only removes the file when every non-blank line is
636	// one of the exact feature-flag lines or the [features] header this package
637	// writes (see isEntireManagedLocalConfig) — a file carrying any unrelated
638	// user content is left alone.
639	func cleanupStaleReservedTreeConfig(repoRoot string) error {
640		configPath := filepath.Join(repoRoot, ".codex", configFileName)
641	
642		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
643		if err != nil {
644			if os.IsNotExist(err) {
645				return nil
646			}
647			return fmt.Errorf("failed to read stale config.toml: %w", err)
648		}
649	
650		if !isEntireManagedLocalConfig(string(data)) {
651			return nil
652		}
653		if err := os.Remove(configPath); err != nil {
654			return fmt.Errorf("failed to remove stale config.toml: %w", err)
655		}
656		return nil
657	}
658	
659	// isEntireManagedLocalConfig reports whether content consists of nothing but
660	// the [features] header and feature-flag lines this package writes (plus blank
661	// lines), with at least one such managed line present. Any other non-blank
662	// line — a user's own setting or a comment — makes the file unmanaged, so
663	// cleanup leaves it untouched.
664	//
665	// The check is line-anchored on purpose. An earlier substring scan could strip
666	// our tokens out of the middle of unrelated content (`webhooks = true`
667	// contains `hooks = true`; a value could contain `[features]`) and, in the
668	// worst case, collapse a file we never wrote to whitespace and delete it. A
669	// whole-line match cannot mistake a user's line for ours.
670	func isEntireManagedLocalConfig(content string) bool {
671		managed := map[string]bool{
672			"[features]":      true,
673			featureLine:       true,
674			legacyFeatureLine: true,
675		}
676		sawManaged := false
677		for _, raw := range strings.Split(content, "\n") {
678			trimmed := strings.TrimSpace(raw)
679			if trimmed == "" {
680				continue
681			}
682			if !managed[trimmed] {
683				return false
684			}
685			sawManaged = true
686		}
687		return sawManaged
688	}
689

